      "requiredSources": "人口统计数据、职住分析、客群调研、集中式公寓存量数据、历史租金数据【网上搜索+实地调研+中指/克尔瑞/贝壳研究院】",
      "sourceKinds": [
        "web_search"
      ],
      "writingLogic": "如中资产涉及住房改造（非居改保）：按照需求分析→供给分析→供需平衡角度展开\n\n【需求分析】按照区/街道/3KM范围内三个维度分析：\n（1）区域人口与就业基础：\n  • 区/街道维度：常住人口、户籍人口、流动人口、18-45岁租房主力人群占比、人均可支配收入\n  • 3KM维度：3KM范围内工作人口数量（如XX万）、职住比（如0.64）、周边产业园/写字楼/产业集群数量及知名企业\n（2）职住分析：\n  • 周边产业集群分布（如科技园/留仙洞/前海等）、就业人口规模与行业结构\n  • 通勤特征：公共交通覆盖（地铁/公交）、平均通勤时间、短通勤需求占比\n  • 职住平衡评估：就业人口与住房供给的匹配度、外溢居住需求规模\n（3）客群画像：\n  • 客群来源：周边5公里产业集群客户、外溢居住需求\n  • 客群分层：年轻科技员工（预算有限、追求性价比、倾向城中村/人才房/合租）、高管及金融科技人才（支付能力强、青睐品质公寓/中高端小区）\n  • 需求特征：通勤效率优先（短通勤需求占比较高）、实用公区依赖（健身房/自习室/共享厨房）、愿意为优质硬装/品牌家电付费、养宠物需求、重视居住私密性\n  • 租金承受能力与户型需求：单间/一房/两房占比、可接受租金区间\n\n【供给分析】对3KM范围内城中村、公寓竞品情况进行分析：\n（1）集中式长租公寓：\n  • 存量统计：3KM范围内集中式公寓项目数量（如62个）、总房源量（如1.74万套）、平均出租率（如95%+）\n  • 竞品明细：分梯队列出代表性项目（开发商自持公寓/品牌白领公寓/酒店式公寓等），阐述建筑面积/距离/户型/租金/出租率/装修标准/公区配套/产品力\n（2）散租/民宅：\n  • 周边住宅小区散租情况、合租/整租单价、出租率\n（3）城中村：\n  • 数量、总房间数、平均租金、改造可能性\n（4）保障性租赁住房/人才房：\n  • 已筹集/在建保租房项目数量、房源量、租金标准、申请条件\n（5）潜在供应：\n  • 3KM范围内在建/待售租赁住房项目（如XX科创城宿舍项目）、预计新增供应规模、入市时间\n\n【供需平衡分析】\n（1）需求总量估算：集中式公寓客群量+分散式客群量=总需求规模，需求覆盖倍数（总需求/项目房源量，如9.4x）\n（2）供给结构评估：存量饱和但结构缺口（中高端精品稀缺，竞品多为老旧/暗房）\n（3）供需结论：需求远大于供给，核心户型无直接竞品，有力支撑首年出租率及租金定价",
