      "writingLogic": "如中资产涉及商业改造（自持改造）：按照需求分析展开\n\n需求分析：重点分析3KM范围内需求情况，同时说明区域近3年租金涨跌情况/区域平均租金等\n  • 3KM范围内常住人口XX万、就业人口XX万、日均客流XX万人次\n  • 周边居民消费能力：人均可支配收入XX元/年，人均消费支出XX元/年\n  • 消费习惯/业态需求：餐饮/零售/休闲娱乐/生活服务需求占比\n  • 区域近3年商业租金涨跌：XX年XX元/㎡/月→XX年XX元/㎡/月，年均涨幅XX%\n  • 区域平均租金：沿街商铺XX元/㎡/月，购物中心XX元/㎡/月，社区商业XX元/㎡/月\n\n供给分析（新增）：\n  • 3KM范围内商业综合体XX个，总商业体量XX万㎡，平均空置率XX%\n  • 沿街商铺XX间，平均租金XX元/㎡/月，空置率XX%\n  • 商圈等级/辐射范围/客流特征\n  • 在建/规划商业项目XX个，预计新增商业体量XX万㎡",
