      "writingLogic": "如中资产涉及住房改造（非居改保）：\n说明项目周边竞品项目分布格局→分梯队对项目周边竞品情况进行分析：\n（1）第一梯队：品牌集中式长租公寓（如开发商自持公寓/连锁品牌公寓），阐述项目名称/距离/建筑面积/房源量/主力户型/租金区间/出租率/装修标准/公区配套/产品力/竞争力\n（2）第二梯队：酒店式公寓/服务式公寓，阐述项目名称/距离/户型/租金/出租率/装修标准/服务配套/竞争力\n（3）第三梯队：城中村/散租民宅/人才房，阐述体量/租金/出租率/产品形态/竞争力\n（4）潜在竞品：在建/待售租赁住房项目，阐述预计供应规模/入市时间/产品定位\n每个梯队阐述建筑面积/距离/特色、竞争力等情况\n表：项目周边竞品对比表（户型/租金/出租率/装修标准/公区配套/产品力多维度对比）\n\n专项法：【适用条件】如本项目拟采用LOFT改造方案，则需对区域内LOFT竞品进行专项分析。【分析维度】①层高对比（竞品LOFT的原始层高/上层净高/下层净高，判断本项目层高是否具有优势）；②空间舒适性（上层是否有横梁影响站立/上层净高是否满足基本使用/中空区域大小）；③户型格局（LOFT一房一厅/两房一厅的面积分布/功能分区合理性）；④租金水平（LOFT产品的月租金/全费用单价/与同面积平层的溢价率）；⑤产品品质（装修标准/家具家电配置/公区配套/运营服务）；⑥去化情况（出租率/空置率/换租频率/客户评价）。\n【对比结论逻辑】通过LOFT竞品专项分析，判断：①区域内LOFT产品的市场接受度（出租率/租金溢价/客户反馈）；②本项目LOFT方案的竞争优势（层高更高/户型更合理/装修更好/价格更低）；③LOFT产品的目标客群特征（年龄/职业/收入/偏好）；④LOFT改造的额外成本能否通过租金溢价覆盖。如区域内LOFT竞品出租率高、租金溢价明显、客户反馈好，则支持本项目采用LOFT方案。\n\n分类法：【竞品5档分类逻辑】根据产品定位和租金水平，区域内租赁住房通常分为5档：①紧凑型公寓（工业区配套宿舍改造，紧凑单间为主，装修标准一般，全费用单价约70-90元/㎡/月）；②普通公寓（传统二房东改造或早期品牌公寓，传统装修，全费用单价约90-110元/㎡/月）；③中高端白领公寓（品牌运营商打造，品质装修，公区配套较好，全费用单价约100-120元/㎡/月）；④中高端LOFT公寓（层高≥3.6米改造的LOFT产品，品质一/两房，空间感强，全费用单价约100-130元/㎡/月）；⑤普通出租房（城中村/小区商品房/工业区宿舍分散出租，普通装修，全费用单价约60-80元/㎡/月）。\n【全费用单价逻辑】竞品对比不能只看租金，需计算\"全费用平均单价\"=（月租金+月管理费+月网费+其他固定费用）/建筑面积，单位为元/㎡/月。需收集的竞品信息包括：①基本信息（项目名称/地址/距地铁距离/建筑年代/产品类型）；②户型信息（户型格局/建筑面积/楼层/是否有阳台/电梯配置）；③费用信息（月租金/月管理费/网费/水费单价/电费单价/是否含家具家电）；④配套信息（家具家电配置/公区配套/运营服务/品牌）。通过全费用单价对比，才能准确判断项目的价格竞争力。",
