      "projectType": "gaibao",
      "chapter": "第五章 项目策划定位",
      "section": "5.2客群画像分析",
      "subsection": "",
      "pointTitle": "",
      "displayTitle": "",
      "requiredSources": "消费者调研报告、人口统计数据【知识库】、城市人口大数据平台、街道统计年鉴、交通出行大数据、职住分析数据【网上搜索+大数据平台】、客群调研问卷、同类项目客户画像、收入水平分析【实地调研+手动填入】",
      "sourceKinds": [
        "knowledge_base",
        "web_search",
        "manual_upload"
      ],
      "writingLogic": "分析法：按照\"区域人口基础→消费/需求特征→客群分层定位\"三层逻辑展开，先摸清区域人口盘子，再分析需求特征，最后明确项目核心客群，具体如下:\n（1）区域人口基础分析：分析项目辐射范围内（3km）的人口总量、人口结构（年龄分布/性别比例/户籍与流动人口占比/家庭结构）、就业分布（周边产业园/写字楼/商业体就业人口数量与行业分布）→明确区域人口基本盘\n（2）需求特征分析：\n  • 非居改保（住房租赁）：分析区域租房人口规模/租金承受能力区间/户型需求（单间/一房/两房占比）/通勤需求（对地铁/公交的依赖度）/配套需求（对商业/教育/医疗的关注度）/核心消费痛点（如通勤远/租金高/品质差/配套缺）\n  • 商业改造：分析区域人均可支配收入/消费支出结构/消费偏好（餐饮/零售/休闲娱乐/生活服务占比）/消费频次与客单价/核心消费痛点（如便民商业缺/亲子业态少/休闲社交空间不足）\n（3）客群分层与定位：基于人口基础和需求特征，将客群分为核心客群/次核心客群/边缘客群三层→明确各层级客群的人口规模占比、需求特征、产品适配方向→最终确定项目目标客群定位\n  • 非居改保核心客群示例：新市民/年轻白领/产业工人/引进人才等\n  • 商业改造核心客群示例：周边社区家庭/办公白领/公园休闲客流等\n\n数据法：【逻辑框架】通过大数据分析区域人口结构和职住关系，为客群定位提供数据支撑：①人口规模（街道/片区内工作人口数/居住人口数/常住人口总量）；②职住关系（居住在本区域但在其他区域工作的人口比例，即\"职住比\"或\"跨区通勤比例\"；工作在本区域但居住在其他区域的人口比例）；③人口来源（居住人口的主要来源地，如周边行政区/地铁沿线区域/产业聚集区）；④职业分布（白领/一般职员/工人/服务业从业人员/企业主/个体工商户等的比例）；⑤年龄结构（20-25岁/25-30岁/30-35岁/35-40岁/40岁以上的比例）；⑥收入水平（月收入区间分布/支付能力评估）；⑦通勤方式（地铁/公交/自驾/步行/骑行的比例，平均通勤时间）。\n【应用逻辑】①根据职住关系判断项目客源：如跨区通勤比例高，说明项目可吸引在周边产业区工作但在本区域居住的客群；如地铁沿线通勤便利，可吸引更远区域的客群；②根据职业分布确定主力客群：如白领/一般职员占比高，则主力户型为一居/两居，装修标准偏品质型；如工人/服务业占比高，则主力户型为单间/小一居，装修标准偏实用型；③根据年龄结构确定产品偏好：25-35岁客群偏好LOFT/智能化/社交公区/品牌公寓，35岁以上客群偏好实用性/性价比/家庭户型；④根据收入水平确定租金承受力：结合客群月收入和租金收入比（通常租金占月收入的25%-35%为合理区间），测算可承受的租金上限。",
      "importance": "★★★重要",
      "outputForm": "文字+数据+表格",
      "note": "",
