      "writingLogic": "分析法：按照\"档次判断→竞品分类调研→分类定价→涨幅与管理费建议\"四步逻辑展开，先定档次，再看竞品，最后分类定价，具体如下:\n（1）项目档次判断：根据项目区位（核心区/一般片区/偏远片区）、硬件条件（建筑结构/改造空间/停车位/电梯）、改造标准（装修标准/智能化配置/公共空间）、目标客群（高端/中端/刚需），综合判断项目档次（高/中/低端）及其适用群体（高管/白领/打工人群等）\n（2）周边竞品分类调研：\n  • 非居改保（住房租赁）：分类调研周边城中村（房间数/平均租金/入住率）、品牌长租公寓（房源量/租金区间/入住率/户型分布/装修标准）、保障性租赁住房/人才房（筹集量/租金标准/申请条件）、在售/待售租赁项目（预计供应/定价）→明确各档次竞品的租金水平和竞争态势\n  • 商业改造：分类调研周边购物中心（各楼层租金/空置率/业态分布/客流）、沿街商铺（租金区间/空置率/业态）、社区商业（租金/空置率/业态）、在售/待售商业项目→明确各档次/各业态竞品的租金水平和竞争态势\n（3）分类价格定位（市场比较法）：\n  • 非居改保（住房租赁）：选取区域内同档次、同类型租赁项目作为可比参照→结合当前市场环境、项目自身条件（地铁距离/周边配套/装修标准/户型布局/楼层朝向，波动幅度-3%~3%）进行综合修正→通过多情景价格研判确定本项目商品租赁均价→一期定价XX元/㎡·月→二期定价XX元/㎡·月→集中定价XX元/㎡·月\n  • 商业改造：选取区域内同档次、同类型商业项目作为可比参照→结合项目自身条件（昭示性/人流动线/楼层/面积/业态适配）进行综合修正→按业态分类定价（餐饮/零售/休闲娱乐/生活服务/亲子教育各业态租金区间）→按位置分类定价（一层/二层/内铺/外铺/主力店/次主力店）→确定各业态/各位置租金均价\n（4）分类价格涨幅与管理费建议：\n  • 非居改保（住房租赁）：\n    - 租金涨幅建议：结合片区主流租赁市场规则及保租房政策要求（保租房租金涨幅受政策限制）→采用梯度化递增标准→租赁第1年为项目核心培育期建议不设涨幅→降低商户前期经营压力→快速吸纳商户入驻、夯实氛围→第2年起执行XX%涨幅→后续每年递增XX%\n    - 管理费/物业费建议：参照整租市场水平（核心区租金XX元/㎡·月，一般片区XX元/㎡·月，偏远片区XX元/㎡·月）→结合集团现有利润方综合判定→基础管理费按XX元/㎡计算→租赁期自项目精装修验收合格之日起算→给予XX个月免租期→第XX年起每XX年租金递增XX%\n  • 商业改造：\n    - 租金涨幅建议：结合片区主流社区租赁规则及二期差异化定价逻辑→区域内商铺租金增长率、免租期标准均与租赁年限深度绑定→本项目分租采用梯度化保守租金递增标准→租赁第1年为项目核心培育期建议不设涨幅→降低商户前期经营压力→快速吸纳商户入驻、夯实氛围→第2年起执行XX%涨幅→后续每年递增XX%\n    - 免租期建议：参考片区短租商铺通用规则→本项目分租商铺以装修筹备需求为核心设置免租期→根据租赁面积和周期时间给予1-3个月装修免租期→针对常规短租分租商户→根据商铺面积大小、装修难易程度灵活适配免租时长\n    - 基础管理费建议：参照整租市场水平（核心区租金XX元/㎡·月，一般片区XX元/㎡·月，偏远片区XX元/㎡·月；免租期方面XX）→结合集团现有利润方综合判定→基础管理费按XX元/㎡计算→租赁期自项目精装修验收合格之日起算→给予XX个月免租期→第XX年起每XX年租金递增XX%\n    - 管理费涨幅建议和免租期建议：待租赁公司盈利收回项目改造投入成本后（预计第XX年起）→剩余经营利润由集团与租赁公司按XX%:XX%比例进行分成→采用阶梯式分成机制：项目实现的超额利润越高，租赁公司分成比例相应阶梯式递增；反之利润水平较低时，分成比例亦随之递减\n\n定位法：【逻辑框架】项目竞争定位从\"品质\"和\"价格\"两个维度同时展开：①品质竞争维度：对标区域内中高端公寓/品质商务公寓，依托产品品质（新建/次新房源/LOFT/精装标准）、区域优势（地铁/配套/产业）、国企品牌力（安居集团/乐寓品牌），打造区域代表性项目/非居改保标杆项目，区别于传统紧凑型公寓/普通公寓；②价格竞争维度：保障性租赁住房政策要求租金不超过同地段同品质市场参考租金的90%（即9折定价），项目入市均价需满足政策要求，同时通过价格优势快速抢占市场、实现高出租率。\n【定价逻辑】①先判断项目档次（紧凑型/普通型/中高端型/高端型），确定市场参考租金区间；②再对比周边竞品租金（含租金+管理费+网费的全费用单价），确定项目市场参考价；③按政策要求打9折确定入市均价（如政策有其他折扣要求按政策执行）；④将价格分拆为租金和管理费两部分（租金占主要部分，管理费覆盖运营服务成本），最终实现整体均价目标；⑤不同户型按面积/楼层/朝向/景观等因素设置差异化单价（大户型/高楼层/好朝向单价略高，小户型/低楼层单价略低），但整体均价不超过政策上限。",
