      "requiredSources": "项目策划方案、运营方案【知识库+运营单位提供+手动填入】、集团营销渠道管理办法、同类项目渠道效果数据、获客成本分析【知识库+手动填入】、渠道效果统计表、企业客户合作协议、营销预算分配表【手动填入+数据分析】、集团自持项目运营数据、同类项目爬坡期案例、市场供需分析【知识库+手动填入】、项目位置评估、产品竞争力分析、营销力度评估、季节性因素分析【手动填入+数据分析】、非居改保政策文件、LOFT市场调研报告、同类项目案例、层高实测数据【知识库+网上搜索】、LOFT改造成本测算、租金溢价分析、效益测算表【手动填入+测算引擎】",
