          "requiredSources": "改造方案、设计图纸、产品标准、成本明细【知识库+设计单位/代建单位提供】、集团户型配比指引、同类项目去化数据、目标客群结构分析【知识库+数据分析】、建筑施工图、面积测绘报告、得房率测算表、公摊优化方案【设计单位提供+手动填入】、LOFT层高设计指引、同类项目案例、建筑层高实测数据【知识库+设计单位提供】、不同层高户型配比方案、租金差异化测算、市场需求分析【设计单位提供+测算引擎】、集团公寓户型标准、LOFT设计规范、建筑施工图、净高测算表【知识库+设计单位提供】、户型设计方案、LOFT上下层面积分配表、楼梯设计方案【设计单位提供+手动填入】、外立面现状检测报告、建筑设计规范、消防规范、集团外立面改造标准【知识库+第三方检测】",
          "writingLogic": "【非居改保、居改居等（住房改造）改造规划方案】\n（1）改造模式：\n  • 毛坯+代建模式（前期毛坯交付，后期市场化招标选聘代建方进行装修改造）或自建模式\n  • 选聘专业代建方及品牌公寓运营机构\n（2）改造范围及内容（按专业分类）：\n  • 建筑及消防疏散：建筑定性及消防疏散满足规范，局部根据改造方案优化\n  • 结构：原建筑结构安全评估，必要时局部加固改造\n  • 给排水：给水系统扩容改造、排水系统改造、热水供应系统配置\n  • 暖通：防排烟系统改造、空调系统配置及机位预留\n  • 电气：民水民电改造（独立变压器配置）、消防控制室设置、弱电系统（梯控/门禁/监控）改造、智能水电表配置\n  • 室内精装：户内硬装+公区精装+软装家具家电配置\n（3）公区改造方案：\n  • 社区大堂及动线：公寓主要出入口、集中大堂、候梯厅、人行连廊等动线优化\n  • 架空层/屋顶空间：利用架空层及屋顶空间设置休闲区、绿化区\n  • 公区配套配置：根据目标客群需求配置健身房、自习室、共享厨房、多功能室、快递收发等公共配套，公区面积按户均标准配置\n（4）户内硬装标准（按功能区域分类）：\n  • 入户区域：入户门（满足隔音要求）、智能门锁、吊顶、墙面、地面\n  • 卧室/就寝区：墙面装饰、地面、踢脚线、飘窗台面、空间隔断\n  • 厨房/操作台：墙面易清洁材料、水槽、龙头、操作台台面、橱柜、排烟设施\n  • 起居厅：吊顶及照明、墙面、地面、护窗栏杆\n  • 卫浴：坐便器、花洒、淋浴隔断、置物架、洗面盆、龙头、墙面地面、排风取暖设施\n  • 灯具：采用节能灯具，合理设置主灯+辅助照明+氛围照明\n  • 开关插座：标准化面板，合理配置点位，潮湿区域设防溅盒\n  • 水电表：智能电表、水表，可接入运营管理系统\n（5）户内软装标准（按建筑面积单方造价控制）：\n  • 电器配置：电视、洗衣机（洗烘一体）、冰箱、热水器、油烟机、灶具等基础家电，根据户型面积配置对应规格\n  • 家具配置：玄关收纳、书桌座椅、床及床垫、衣柜、沙发/卡座、窗帘、晾衣设施等基础家具，满足居住基本需求\n（6）智能化改造：\n  • 智能门锁、智能水电表、梯控系统、门禁系统、公共区域智能监控\n（7）改造工期及运营节奏：\n  • 改造工期XX个月，开业时间XX年XX月，出租爬坡期XX个月\n（8）交割前前期工作：\n  • 代建管理服务、精装方案设计、施工图设计、结构鉴定及检测、造价咨询、样板间施工等前期工作，提前启动以实现交割后即刻开工\n\n配比法：【户型配比逻辑】①根据目标客群结构确定一居/两居/三居比例（如单身白领为主则一居占比高，家庭客群为主则两居占比高）；②一居通常占比60%-80%（主力户型，去化快），两居占比20%-40%（补充户型，面向家庭/合租），三居及以上占比0%-10%（如项目定位中高端可适当增加）；③按楼层分配户型：高楼层/景观好的楼层布置大户型，低楼层/靠近电梯或设备区的楼层布置小户型；④户型种类不宜过多（通常3-5种主力户型），便于标准化装修和成本控制。\n【得房率逻辑】①得房率=套内面积/建筑面积×100%，非居改保项目因原建筑为公建/工业用途，公摊面积通常较大，得房率需重点测算；②标准层得房率通常为75%-90%（取决于原建筑平面布局和公摊大小），如原建筑走廊过宽/核心筒过大，得房率可能低于75%；③提高得房率的方法：优化走廊宽度（满足消防疏散前提下压缩）/利用核心筒周边空间/减少不必要的公摊面积/如政策允许可搭建增加使用面积；④套内面积与建筑面积的对应关系需在户型表中明确标注，便于租金测算和客户沟通。\n\n差异法：【逻辑框架】如项目不同楼层存在层高差异（如部分楼层4.5米/部分楼层5.4米），则需按层高分别设计差异化LOFT方案：①层高3.6-4.2米：可做紧凑型LOFT，上层空间较局促，上层净高约1.8-2.0米，适合做睡眠区，需注意横梁对舒适性的影响；②层高4.2-4.8米：可做舒适型LOFT，上层净高约2.0-2.2米，可满足基本站立，上层可做卧室+小型衣帽间/书房；③层高4.8米以上：可做宽敞型LOFT，上层净高≥2.3米，上层空间充裕，可做卧室+衣帽间+书房+收纳等多功能区，产品竞争力最强。\n【差异化策略】①高楼层（层高较高）可做高品质大户型LOFT（两房/三房），面向家庭客群/企业中高层，租金单价更高；②低楼层（层高较低）可做紧凑型小户型LOFT（一房/单间），面向单身白领/新市民，控制总价提高性价比；③如部分楼层已搭建楼板（走廊上方/室内），需咨询住建部门是否可保留使用，如可保留则可降低改造成本；④不同层高的户型配比需结合市场需求和租金测算综合确定。\n\n模块法：【适用条件】如项目层高≥3.6米且政策允许通过钢结构搭建/整体家居定制等方式增加室内使用空间，则可考虑LOFT改造方案。【模块设计逻辑】LOFT户型通常按以下功能模块设计：①玄关模块（入户门/鞋柜/高位收纳）②起居模块（沙发/茶几/电视点位）③寝卧模块（双人床/床头柜，通常位于上层）④卫浴模块（水盆/马桶/淋浴/毛巾架，通常位于下层）⑤厨房模块（洗衣机/冰箱/抽油烟机/操作台，通常位于下层玄关或起居区）⑥收纳模块（鞋柜/衣柜/高位收纳/楼梯收纳，充分利用LOFT垂直空间）。\n【空间分配逻辑】①下层为公共活动区（客厅/餐厅/厨房/卫浴），用于接待及日常活动；上层为私密休息区（卧室/书房/衣帽间），实现动静分区，私密性优于平层；②净高要求：上层净高≥2000mm（保证基本站立舒适度），下层净高≥2200mm（保证公共活动空间不压抑），中空区域净高为原始层高（提升空间感和采光）；③面积分配：上层套内面积通常为下层的60%-100%（取决于层高和搭建方式），建筑面积按产权登记面积计算；④楼梯设计：优先采用收纳楼梯/踏步柜，兼顾通行和收纳功能。",
