      "writingLogic": "预测法：通过系统性升级改造，预测改造后的效果，分非居改保和商业改造两类：\n\n【非居改保（住房改造）改造效果预测】\n（1）产品效果：\n  • 从毛坯/老旧配套宿舍升级为标准化精品白领公寓，户型方正、带阳台、得房率提升\n  • 公区配套完善（健身房/自习室/共享厨房/多功能室），居住体验显著提升\n  • 智能化配置（智能门锁/智能水电表/梯控门禁），运营效率提升\n（2）运营效果：\n  • 起始租金XX元/间/月（建面坪效XX元/㎡/月，套内坪效XX元/㎡/月），较改造前提升XX%\n  • 稳定期出租率XX%（如93%），爬坡期XX个月\n  • 租金涨幅XX%/年（如1.5%），NOI MARGIN XX%（如81.6%）\n（3）财务效果：\n  • 改造成本XX万元（单方XX元/㎡）\n  • 改造IRR XX%、投资回收期XX年\n  • 集团净利润较改造前增加XX万元\n  • 运营方项目净利润XX万元\n（4）社会效果：\n  • 增加保障性租赁住房供给XX套（间），缓解新市民/青年人住房困难\n  • 盘活存量资产，实现国有资产保值增值\n  • 打造保租房标杆项目，形成可复制经验\n\n【商业改造（自持改造）改造效果预测】\n（1）空间效果：从无序破败面貌→有序核心+自然生长的生态，夯实便民生活基础，打造户外休憩与社交场景\n（2）业态效果：引入体验式业态，实现从基础配套到品质生活场景的升级\n（3）经营效果：预计改造后项目平均年总收入为XX万元，较改造前提升XX%，改造资产回报率达到XX%",
