      "projectType": "gaibao",
      "chapter": "第七章 合作协议",
      "section": "7.1项目合作模式",
      "subsection": "",
      "pointTitle": "",
      "displayTitle": "",
      "requiredSources": "合作协议文件、交易文件【手动填入（找集团或区有关部门等）+知识库】、集团收益分配指引、同类项目分成案例、财务测算模型【知识库+测算引擎】、合作协议条款、收益分配测算表、双方谈判记录【手动填入+法务审核】、集团合作模式指引、同类项目合作案例、合作方背景调查【知识库+手动填入】、合作方案测算表、财务模型输出、双方权责划分表【手动填入+测算引擎】、合作模式比选分析报告、风险收益评估表【手动填入+知识库】",
      "sourceKinds": [
        "knowledge_base",
        "manual_upload",
        "calculation_engine"
      ],
      "writingLogic": "罗列法：按照相关协议文件，详细描述项目的合作模式情况\n\n（1）交易方式：资产收购/股权收购（明确选择哪种及原因）\n（2）投资主体：母基金直投/子基金投资（明确基金名称及架构）\n（3）合作方：合作方名称、持股比例、合作分工（如深安居集团等）\n（4）交易对手：项目公司名称、股东及实际控制人、资信情况\n（5）运营模式：整体租赁模式/委托运营模式/合作分成模式，明确投资运营方及权责划分\n（6）退出方式：大宗交易退出/REITs退出（公募/私募）/长期自持，明确投资期限及退出路径\n\n分成法：【逻辑框架】如采用收益分成模式，通常按\"优先收回投资+梯度分成\"的三阶段机制设计：①成本优先回收阶段（运营前期，投资方获取绝大部分租金净收益以快速收回改造投入，如当年收益不足则缺额顺延至下一阶段补齐）②阶梯过渡分成阶段（成本回收后，逐步提高产权方分成比例，向常态化收益模式过渡）③固定比例分成阶段（进入稳定运营期后，双方按约定固定比例分配租金收益，保障长期稳定回报）。\n【适用说明】收益分成模式有多种实现方式，以下\"优先收回投资+梯度分成\"三阶段机制为常见模式之一，供参考，具体分成方式由双方谈判确定。\n\n【梯度分成三阶段逻辑（供参考）】①成本优先回收阶段（运营前期，投资方获取绝大部分租金净收益以快速收回改造投入，如当年收益不足则缺额顺延至下一阶段补齐）②阶梯过渡分成阶段（成本回收后，逐步提高产权方分成比例，向常态化收益模式过渡）③固定比例分成阶段（进入稳定运营期后，双方按约定固定比例分配租金收益，保障长期稳定回报）。\n\n【其他常见分成模式】①固定比例分成（不设成本回收期，合作期内始终按固定比例分成）②保底+超额分成（产权方收取固定保底租金，超额部分双方按比例分成）③阶梯租金（按运营年限逐年递增租金，不涉及收益分成）④纯固定租金（不涉及分成，投资方按固定单价支付租金）。具体模式选择需结合双方风险偏好、谈判地位、项目收益预测等因素综合确定。\n\n比选法：【逻辑框架】非居改保项目通常有三类合作模式可选，需从多维度比选后确定最优模式：①固定底租模式（投资方按现状承租物业，约定固定底租单价，即\"二房东\"模式，改造后委托运营）②\"提供合格房源+约定收益分成\"包租模式（产权方按约定标准完成基础改造达到\"合格房源\"要求后，投资方再介入装修运营，不承诺固定租金，按约定比例收益分成）③\"轻资产\"模式（产权方投资改造后委托运营方运营，运营方仅收取服务费）。\n【比选维度】①合作思路与权责划分（谁投资改造/谁负责运营/谁承担市场风险）②改造成本收回机制（通过固定租金收回/通过优先收益分成收回/通过服务费收回）③存在问题与优势（固定底租模式：产权方收益低可能影响合作意愿，投资方改造投入大且市场风险高；收益分成模式：风险共担利益共享，发挥各自优势，但需明确分工边界；轻资产模式：投资方无投资风险但无法锁定长期收益，无法发挥属地优势）④经济指标对比（双方改造投资额/运营收益额/内部收益率IRR）。\n【决策结论逻辑】综合对比后，选择\"风险与收益最佳平衡\"的模式。通常\"提供合格房源+约定收益分成\"模式较优：产权方负责风险较高/后期投诉较多的改造（结构与消防改造/高空作业/整体家居定制等），投资方借助集团集采和品控优势负责室内装饰/卫浴/门锁等改造，运营收益优先用于投资方收回改造投入，双方风险共担利益共享。",
