      "writingLogic": "罗列法：按照相关协议文件，重点分点罗列项目合作的核心条款\n\n（1）交易价格及支付方式：交易总价、首付款比例、尾款支付条件及时间节点\n（2）融资方案：\n  • 贷款额度XX万元，杠杆率XX%（如60%）\n  • 贷款年限XX年（如25年），贷款利率XX%（如3.00%）\n  • 贷款类型（如住房租赁支持贷款）\n（3）担保措施：土地使用权抵押/在建工程抵押/项目公司股权质押/连带责任担保等\n（4）交割条件及交割安排：交割前提条件、交割时间、交割资产范围\n（5）改造及运营约定：改造标准、改造工期、运营机构选聘、运营指标要求（出租率/租金/NOI）\n（6）收益分配：基础管理费+超额分成模式，分成比例（如集团与运营方XX%:XX%），分成触发条件（如运营方收回改造成本后）\n（7）退出约定：退出触发条件、退出方式、优先购买权等\n（8）违约责任及争议解决\n\n防控法：【逻辑框架】合作协议中需设置以下关键防控条款：①排他合作期（合作意向达成后至正式协议生效前，约定一定期限的排他合作期，产权方不得与第三方就本项目保租房改建开展合作）②合作期限（通常5-10年，期满后协商续约）③提前终止赔偿（如因产权方原因/政府政策等非投资方原因导致合作提前终止，产权方需一次性全额赔付投资方已发生的全部改造工程投资成本+财务资金成本+合同期内可预期经营收益）④产权方履约担保（产权方未按约定时限完成配套施工并满足运营标准的，投资方可代为实施，增量成本从产权方应得收益中抵扣）⑤权属及合规保证（产权方保证合作资产权属清晰，不存在查封/异议/违法建设等情形，符合改造为保租房的基础条件）⑥风险共担原则（市场环境/行业政策/住房保障调控政策等风险由双方按收益分配逻辑共同承担；因单方履职不当造成的问题由责任方自行承担）。\n\n分摊法：【逻辑框架】如采用分工合作模式，需明确双方各自负责的改造内容及对应成本，核心原则是\"发挥各自优势、风险与能力匹配\"：①产权方通常负责：质量结构检测鉴定/方案设计及施工图设计/拆除新建工程（含LOFT钢架/卫生间墙体拆除）/结构加固/强弱电工程（公区及户内主管线）/给排水工程（公区主管线）/消防工程（公区）/水电表及网关/家电采购/家具（含LOFT整体家居定制）/公区装修（电梯前室/走廊墙地砖/天花吊顶）/空调格栅百叶等外立面改造/建安工程一切险及配合费/暂列金等。②投资方通常负责：户内装修（天花腻子油漆/地面瓷砖/墙面装饰板）/户内电气配管配线及面板灯具/窗帘工程/VI标识工程/卫浴洁具安装/户内给排水工程/户内烟道工程/入户门/智能门锁/铝合金门窗（户内卫生间门/厨房平开门）等。\n【成本估算逻辑】①各方按负责的改造内容分别估算成本，计算单方造价（元/㎡建筑面积）和总投资额（万元）②产权方负责的内容通常单方造价较高（含结构/消防/家电/家具等），投资方负责的户内装修单方造价相对较低③成本估算需参考集团集采价格、同类项目实际造价、市场询价等④如涉及LOFT改造，LOFT整体家居定制/钢结构搭建为成本大头，需单独列项⑤暂列金（签证变更项）通常按总造价的一定比例预留。",
